import codecs
def nested(error):
    return (input(), -1)
def outer(error):
    return (('\ud800' + 'Z').encode('ascii', 'nested_service'), -1)
codecs.register_error('nested_service', nested)
codecs.register_error('outer_service', outer)
print(('\udfff' + 'A').encode('ascii', 'outer_service'))

